use vstd::prelude::*;

verus! {
    fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
        ensures
            result.len() == a.len(),
            forall |i: nat| 0 <= i < result.len() ==> result[i] == 1,
    {
        let mut result: Vec<i32> = Vec::new();
        let len = a.len() as nat;

        // Preallocate the result vector with the same length as the input vector
        result.reserve(len as usize);

        let mut idx: nat = 0;
        while idx < len
            invariant
                idx <= len,
                result.len() == idx,
                forall |j: nat| 0 <= j < idx ==> result[j] == 1,
            decreases len - idx,
        {
            result.push(1);
            idx = idx + 1;
        }

        result
    }
}

